import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as lib from './lib.js';

test('八个函数都在', () => {
  for (const n of ['add', 'sub', 'mul', 'div', 'clamp', 'sum', 'avg', 'median', 'describe']) {
    assert.equal(typeof lib[n], 'function', `缺 ${n}`);
  }
});

test('算得对', () => {
  assert.equal(lib.add(1, 2), 3);
  assert.equal(lib.sub(5, 2), 3);
  assert.equal(lib.mul(3, 4), 12);
  assert.equal(lib.div(9, 3), 3);
  assert.equal(lib.clamp(5, 1, 3), 3);
  assert.equal(lib.clamp(0, 1, 3), 1);
  assert.equal(lib.sum([1, 2, 3]), 6);
  assert.equal(lib.avg([1, 2, 3]), 2);
  assert.equal(lib.median([3, 1, 2]), 2);
  assert.equal(lib.median([4, 1, 3, 2]), 2.5);
  assert.deepEqual(lib.describe([1, 2, 3]), { n: 3, sum: 6, avg: 2, median: 2 });
});

test('错误情况都要抛', () => {
  for (const f of [() => lib.add('a', 1), () => lib.div(1, 0), () => lib.clamp(1, 3, 1), () => lib.avg([]), () => lib.median([])]) {
    assert.throws(f);
  }
});

