// 第 1 轮定下的两条规矩，到最后一轮还守着吗？
import fs from 'node:fs';

const src = fs.readFileSync('lib.js', 'utf8');
const lines = src.split('\n');
const problems = [];

// 规矩 1：每个 export function 上方紧邻必须有 JSDoc 收尾行
lines.forEach((line, i) => {
  const m = /^\s*export\s+(async\s+)?function\s+([A-Za-z0-9_$]+)/.exec(line);
  if (!m) return;
  let j = i - 1;
  while (j >= 0 && lines[j].trim() === '') j -= 1;
  if (j < 0 || !lines[j].trim().endsWith('*/')) problems.push(`export ${m[2]}（第 ${i + 1} 行）上方没有 JSDoc`);
});

// 规矩 2：不许裸 throw new Error
lines.forEach((line, i) => {
  if (/throw\s+new\s+Error\s*\(/.test(line)) problems.push(`第 ${i + 1} 行有裸的 throw new Error`);
});

if (problems.length) {
  console.error('早期约束已被破坏：\n- ' + problems.join('\n- '));
  process.exit(1);
}
console.log('两条约束都还在');
